#!/usr/bin/env python3
"""Shipped-order reconciliation, Mar-May 2025 (UTC).

Fetches every /orders page and the customers the calculation needs, then computes the totals.
Pages and customers already on disk are reused, so the script can be re-run after an interruption.
"""
import email.utils
import json
import os
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
WORK = "/tmp/recon"
PAGE_DIR = os.path.join(WORK, "pages")
CUSTOMER_FILE = os.path.join(WORK, "customers.json")
LOG_FILE = os.path.join(WORK, "fetch.log")
RESULT_FILE = os.path.join(WORK, "result.json")
MAX_ATTEMPTS = 40
REGIONS = ("north", "south", "east", "west")
WINDOW_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
WINDOW_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive, so all of 31 May counts


def log(msg):
    line = f"{time.strftime('%H:%M:%S')} {msg}"
    print(line, flush=True)
    with open(LOG_FILE, "a") as f:
        f.write(line + "\n")


def write_json(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(data, f)
    os.replace(tmp, path)


def raw_get(url, headers=None, method="GET"):
    """Return (status, headers, body) for any HTTP status instead of raising."""
    req = urllib.request.Request(url, headers=headers or {}, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as err:
        return err.code, err.headers, err.read()


def retry_after_seconds(headers, body):
    value = headers.get("Retry-After")
    if value is None:
        raise RuntimeError(f"429 without Retry-After; body={body[:300]!r}")
    try:
        return float(value)
    except ValueError:
        when = email.utils.parsedate_to_datetime(value)
        return (when - datetime.now(timezone.utc)).total_seconds()


class Api:
    def __init__(self):
        self.token = None

    def new_token(self):
        status, _, body = raw_get(f"{BASE}/token", method="POST")
        if status != 200:
            raise RuntimeError(f"token request failed: HTTP {status} {body[:200]!r}")
        self.token = json.loads(body)["token"]

    def get(self, path, auth=True, not_found_ok=False):
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.new_token()
            headers = {"Authorization": f"Bearer {self.token}"} if auth else {}
            try:
                status, resp_headers, body = raw_get(BASE + path, headers)
            except OSError as err:
                log(f"{path} attempt {attempt}: transport error {err!r}")
                time.sleep(min(2 ** attempt, 30))
                continue
            if status == 200:
                try:
                    return json.loads(body)
                except ValueError:
                    log(f"{path} attempt {attempt}: 200 but body is not JSON: {body[:200]!r}")
                    time.sleep(min(2 ** attempt, 30))
                    continue
            if status == 404 and not_found_ok:
                return None
            log(f"{path} attempt {attempt}: HTTP {status} {dict(resp_headers)} {body[:300]!r}")
            if status == 401:
                self.token = None  # token expired: fetch a new one and repeat the same request
            elif status == 429:
                wait = retry_after_seconds(resp_headers, body)
                log(f"rate limited; waiting {wait:.1f}s as instructed")
                time.sleep(wait + 1)
            elif status >= 500:
                time.sleep(min(2 ** attempt, 30))
            else:
                raise RuntimeError(f"{path}: unexpected HTTP {status}")
        raise RuntimeError(f"{path}: gave up after {MAX_ATTEMPTS} attempts")


def load_pages(api):
    os.makedirs(PAGE_DIR, exist_ok=True)
    pages = []
    number = 1
    while True:
        cache = os.path.join(PAGE_DIR, f"page-{number:03d}.json")
        if os.path.exists(cache):
            with open(cache) as f:
                page = json.load(f)
        else:
            page = api.get(f"/orders?page={number}")
            if page.get("page") != number:
                raise RuntimeError(f"asked for page {number}, service returned page {page.get('page')}")
            write_json(cache, page)
        log(f"page {number}/{page['total_pages']}: {len(page['items'])} items, next={page['next']!r}")
        pages.append(page)
        if number >= page["total_pages"]:
            return pages
        number += 1


def load_customers(api, customer_ids):
    customers = {}
    if os.path.exists(CUSTOMER_FILE):
        with open(CUSTOMER_FILE) as f:
            customers = json.load(f)
    for cid in sorted(customer_ids):
        if cid not in customers:
            customers[cid] = api.get(f"/customers/{cid}", not_found_ok=True)
            write_json(CUSTOMER_FILE, customers)
    return customers


def utc_time(placed_at):
    text = placed_at[:-1] + "+00:00" if placed_at.endswith("Z") else placed_at
    stamp = datetime.fromisoformat(text)
    if stamp.tzinfo is None:
        raise ValueError(f"placed_at has no offset: {placed_at!r}")
    return stamp.astimezone(timezone.utc)


def discounted_cents(amount_cents, discount_pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, in exact integer arithmetic."""
    return (amount_cents * (100 - discount_pct) + 50) // 100


def main():
    api = Api()
    pages = load_pages(api)

    listings = [item for page in pages for item in page["items"]]
    orders = {}
    duplicates = 0
    conflicts = []
    for item in listings:
        if item["id"] in orders:
            duplicates += 1
            if orders[item["id"]] != item:
                conflicts.append(item["id"])
        else:
            orders[item["id"]] = item

    qualifying = [
        o for o in orders.values()
        if o["status"] == "shipped" and WINDOW_START <= utc_time(o["placed_at"]) < WINDOW_END
    ]

    customers = load_customers(api, {o["customer_id"] for o in qualifying})
    by_region = {region: 0 for region in REGIONS}
    for o in qualifying:
        customer = customers[o["customer_id"]]
        if customer is None:
            raise RuntimeError(f"customer {o['customer_id']} not found (order {o['id']})")
        by_region[customer["region"]] += discounted_cents(o["amount_cents"], customer["discount_pct"])

    result = {
        "total_cents": sum(by_region.values()),
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    write_json(RESULT_FILE, result)
    log(f"listings={len(listings)} distinct={len(orders)} duplicates={duplicates} conflicting_duplicates={len(conflicts)}")
    log(f"result: {json.dumps(result)}")


if __name__ == "__main__":
    main()

